(() => {
'use strict';
const host=document.createElement('section');host.id='race-app';host.hidden=true;document.body.append(host);
const storage={get(k,d=''){try{return localStorage.getItem(k)||d;}catch{return d;}},set(k,v){try{localStorage.setItem(k,v);}catch{}}};
let base=storage.get('race.api',window.RACE_API_BASE||'').replace(/\/$/,''),token=storage.get('race.token'),me='',nickname='',game='repair',mode='easy',state=null,pollTimer=0,clockTimer=0,gameKey='',viewKey='',busy=false,offset=0,page='menu',closed=true,generation=0,transitionTimer=0,pendingState=null,transitionKey='',streamEnabled=false,socket=null,heartbeatTimer=0,lastStreamAt=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>{n=Math.max(0,n||0);return `${Math.floor(n/60000).toString().padStart(2,'0')}:${(n%60000/1000).toFixed(2).padStart(5,'0')}`;};
const gameName=()=>game==='repair'?'修复机器人':'浮空回收';
const engine=()=>game==='repair'?window.RepairGame:window.SalvageGame;
const gameHost=()=>document.getElementById(game==='repair'?'repair-app':'salvage-app');
function cancelTransition(){clearTimeout(transitionTimer);transitionTimer=0;pendingState=null;host.querySelector('.race-complete')?.remove();}
function stopGame(){engine()?.stopRace();gameKey='';document.body.classList.remove('race-active');}
function clearPolling(){clearTimeout(pollTimer);clearInterval(clockTimer);clearInterval(heartbeatTimer);generation++;if(socket){socket.onclose=null;socket.close();socket=null;}}
async function api(path,data){const began=performance.now();let response;try{response=await fetch(base+'/api/'+path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},...(data===undefined?{}:{body:JSON.stringify(data)}),signal:AbortSignal.timeout(8000)});}catch{throw Error('竞速服务连接失败，请检查服务地址与网络。');}let result;try{result=await response.json();}catch{throw Error('竞速服务尚未部署，请先启动本地服务或设置服务器地址。');}if(!response.ok)throw Error(result.error||'请求失败');if(result.serverNow)offset=result.serverNow-(Date.now()-(performance.now()-began)/2);return result;}
function notice(text){const el=host.querySelector('[data-race-notice]');if(el)el.textContent=text;}
function shell(body){host.hidden=false;host.className='race-menu';host.innerHTML=`<header><button data-act="back">‹ 返回</button><span>${gameName()} / 竞速挑战</span></header><main><div class="race-wordmark" aria-hidden="true">// ENDFIELD<span>SIMULATION TERMINAL / RACE</span></div>${body}<p data-race-notice role="status"></p></main>`;}
function menu(){cancelTransition();clearPolling();stopGame();page='menu';viewKey='';shell(`<small>RACE CHALLENGE</small><h1>竞速挑战</h1><div class="race-settings"><label>昵称 <input id="race-name" maxlength="20" value="${esc(nickname)}" placeholder="管理员xxxx"></label><label>难度 <select id="race-mode"><option value="easy" ${mode==='easy'?'selected':''}>简单模式</option><option value="chaos" ${mode==='chaos'?'selected':''}>混沌模式</option></select></label></div><div class="race-options"><article><span class="race-index">01 / SOLO CHALLENGE</span><h2>个人竞速</h2><p>随机 5 题 · 挑战你的最快记录</p><button data-act="solo">开始</button><button data-act="leaderboard">排行榜</button><button data-act="history">个人历史</button></article><article><span class="race-index">02 / ONLINE MATCH</span><h2>联机竞速</h2><p>双人同题 · BO5 / BO7 / BO9</p><label>赛制 <select id="race-count"><option value="5">BO5（5 局 3 胜）</option><option value="7">BO7（7 局 4 胜）</option><option value="9">BO9（9 局 5 胜）</option></select></label><button data-act="create">创建房间</button><div><input id="race-code" maxlength="6" placeholder="输入房间码"><button data-act="join">加入</button></div></article></div><p class="race-rule">简单模式采用对称布局；混沌模式随机布局。每题均由服务器生成并验证可解。</p><details><summary>连接设置</summary><label>竞速服务器地址 <input id="race-api" placeholder="本地运行时留空" value="${esc(base)}"></label><button data-act="connect">连接</button><p>公开排行榜与联机需要连接同一台服务器。成绩绑定当前浏览器身份，昵称可以重复。</p></details>`);document.querySelector('.terminal').inert=true;}
async function connect(){const auth=await api('session',{});streamEnabled=auth.websocket===true;token=auth.token;me=auth.user;nickname=auth.nickname;storage.set('race.token',token);const input=host.querySelector('#race-name');if(input&&!input.value)input.value=nickname;return auth;}
async function open(g){clearPolling();closed=false;game=g;state=null;menu();notice('正在连接竞速服务…');try{await connect();const s=await api('state');notice('已连接');if(s.active){game=s.game;apply(s);startPolling();}}catch(e){notice(e.message);}}
async function identity(){if(!me)await connect();const name=host.querySelector('#race-name')?.value||nickname;mode=host.querySelector('#race-mode')?.value||mode;if(name!==nickname){await api('nickname',{nickname:name});nickname=name;}}
function startPolling(){if(streamEnabled&&typeof WebSocket!=='undefined'){startStream();return;}clearPolling();const gen=generation;const poll=async()=>{if(closed||gen!==generation)return;try{const s=await api('state');if(gen===generation)apply(s);}catch(e){notice(e.message+' 超过 20 秒失联会判负。');}if(gen===generation)pollTimer=setTimeout(poll,350);};pollTimer=setTimeout(poll,350);clockTimer=setInterval(updateClock,50);}
function startStream(){
 if(socket&&(socket.readyState===0||socket.readyState===1))return;
 clearPolling();const gen=generation;clockTimer=setInterval(updateClock,50);
 const endpoint=new URL(base+'/api/stream',location.href);endpoint.protocol=endpoint.protocol==='https:'?'wss:':'ws:';
 const ws=new WebSocket(endpoint.href,['endfield-race','auth.'+token]);socket=ws;lastStreamAt=Date.now();
 ws.onopen=()=>{if(gen!==generation)return;notice('');ws.send(JSON.stringify({type:'ping'}));heartbeatTimer=setInterval(()=>{if(gen!==generation)return;if(Date.now()-lastStreamAt>18000){ws.close();return;}if(ws.readyState===1)ws.send(JSON.stringify({type:'ping'}));},6000);};
 ws.onmessage=e=>{if(gen!==generation)return;try{const event=JSON.parse(e.data);if(event.type==='state'){lastStreamAt=Date.now();if(event.state.serverNow)offset=event.state.serverNow-Date.now();apply(event.state);}}catch{notice('同步数据异常，正在重连…');ws.close();}};
 ws.onerror=()=>notice('实时连接暂时中断，正在重连…');
 ws.onclose=()=>{if(gen!==generation||closed)return;socket=null;clearInterval(heartbeatTimer);notice('连接中断，正在重连；超过 20 秒会判负。');pollTimer=setTimeout(()=>{if(gen===generation&&!closed)startStream();},1500);};
}
function apply(s){if(closed)return;
 if(transitionTimer){if(!pendingState||s.serverNow>=pendingState.serverNow)pendingState=s;return;}
 const completed=state&&s.id===state.id&&page==='playing'&&s.log?.find(x=>x.round===state.round&&x.winner);
 const completedKey=completed?s.id+':'+completed.round:'';
 if(completed&&completedKey!==transitionKey){
  transitionKey=completedKey;pendingState=s;const own=completed.winner===me;
  const overlay=document.createElement('div');overlay.className='race-complete '+(own?'is-own':'is-opponent');overlay.setAttribute('role','status');
  overlay.innerHTML=`<div class="race-complete-scan"></div><div class="race-complete-band"><span class="race-complete-mark">${own?'✓':'↗'}</span><div><small>${own?'MISSION COMPLETE':'OPPONENT COMPLETE'}</small><strong>${own?(game==='repair'?'修复完成':'回收成功'):'对方已完成'}</strong><p>${s.status==='ended'?'正在汇总结算': '即将进入下一关'}</p></div></div>`;
  host.append(overlay);gameHost().inert=true;
  transitionTimer=setTimeout(()=>{const next=pendingState;cancelTransition();if(next)apply(next);},1000);return;
 }
if(state&&s.id===state.id&&(s.serverNow<state.serverNow||s.round<state.round))return;state=s;if(!s.active){menu();notice('房间已关闭、已过期，或你已被移出。');return;}game=s.game;mode=s.mode;
 if(s.status==='lobby'){stopGame();page='room';const key=JSON.stringify([s.id,s.players,s.mode,s.count]);if(viewKey!==key){viewKey=key;shell(`<small>ONLINE / LOBBY</small><h1>房间 ${esc(s.code)}</h1><button data-act="copy-room">复制房间码</button><div class="race-players">${s.players.map(p=>`<div>${esc(p.nickname)} ${p.id===s.host?'· 房主':''}${p.id===me?' · 你':''}</div>`).join('')}${s.players.length===1?'<p>等待另一名玩家加入…</p>':''}</div><label>难度 <select id="room-mode" ${me===s.host?'':'disabled'}><option value="easy" ${s.mode==='easy'?'selected':''}>简单模式</option><option value="chaos" ${s.mode==='chaos'?'selected':''}>混沌模式</option></select></label><label>赛制 <select id="room-count" ${me===s.host?'':'disabled'}>${[5,7,9].map(n=>`<option value="${n}" ${n===s.count?'selected':''}>BO${n}</option>`).join('')}</select></label>${me===s.host?`<button data-act="configure">保存设置</button><button data-act="kick" ${s.players.length<2?'disabled':''}>移出对方</button><button data-act="start" ${s.players.length<2?'disabled':''}>开始</button>`:'<p>等待房主开始</p>'}<button data-act="leave">退出房间</button>`);}return;}
 if(s.status==='ended'){stopGame();const key='end'+s.id+JSON.stringify(s.result)+s.elapsed+s.canRematch;if(viewKey!==key){page='result';viewKey=key;const who=s.players.find(p=>p.id===s.result?.winner);shell(`<small>RACE / RESULT</small><h1>${s.solo?(s.elapsed?'挑战完成':'挑战结束'):(who?esc(who.nickname)+' 获胜':'平局')}</h1><p>${esc(s.result?.reason)}</p>${s.solo&&s.elapsed?`<strong class="race-result-time">${fmt(s.elapsed)}</strong><p>个人最佳 ${fmt(s.best)} · 排名 #${s.rank}${s.newBest?' · 新纪录':''}</p>`:scoreboard(s)}<button data-act="review">看答案 / 复制种子</button>${s.solo?'<button data-act="again">再来一局</button>':s.canRematch===false?'<p>对方已离开，可返回菜单创建新房间。</p>':me===s.host?'<button data-act="start">再来一局</button>':'<button data-act="wait">返回房间等待</button>'}<button data-act="leave">返回竞速菜单</button>`);}return;}
 page='playing';viewKey='';const key=s.id+':'+s.round;
 if(gameKey!==key){stopGame();gameKey=key;host.className='race-playing';host.innerHTML=`<div class="race-hud"><b data-race-progress></b><span data-race-score></span><time data-race-time></time><button data-act="skip" ${s.solo?'hidden':''}>申请跳过</button><button data-act="leave">退出${s.solo?'挑战':'（判负）'}</button><p data-race-notice role="status"></p></div><div class="race-curtain"><div class="race-countdown-panel"><small>PREPARE / 准备开始</small><strong data-race-countdown></strong><span class="race-countdown-line"></span></div></div>`;document.body.classList.add('race-active');engine().startRace(s.level,{onExit:()=>act('leave'),onComplete:submit});document.querySelector('.terminal').inert=true;gameHost().inert=true;api('loaded',{round:s.round}).then(apply).catch(e=>notice(e.message));}
 host.querySelector('[data-race-progress]').textContent=`${s.mode==='easy'?'简单':'混沌'} · 第 ${s.round+1}/${s.count} 题`;
 host.querySelector('[data-race-score]').innerHTML=scoreboard(s);
 const skip=host.querySelector('[data-act="skip"]');if(skip)skip.textContent=s.players.find(p=>p.id===me)?.skip?'撤销跳过':'申请跳过';updateClock();
}
function scoreboard(s){
 if(s.solo)return `<div class="race-solo-progress"><span>已完成</span><strong>${s.players[0].score}<em> / ${s.count}</em></strong></div>`;
 const players=[...s.players].sort((a,b)=>(b.id===me)-(a.id===me));
 return `<div class="race-scoreboard" aria-label="比赛比分">${players.map((p,i)=>`${i?'<span class="race-score-divider">:</span>':''}<div class="race-score-player ${p.id===me?'is-me':'is-rival'}"><div class="race-score-name" title="${esc(p.nickname)}"><span>${p.id===me?'你':'对手'}</span><b>${esc(p.nickname)}</b></div><strong>${p.score}</strong><div class="race-score-pips">${Array.from({length:(s.count+1)/2},(_,j)=>`<i class="${j<p.score?'is-scored':''}"></i>`).join('')}</div>${p.skip?'<small>申请跳过</small>':''}</div>`).join('')}</div>`;
}
function updateClock(){if(transitionTimer){gameHost().inert=true;return;}if(page!=='playing'||!state)return;const now=Date.now()+offset,waiting=state.status==='loading'||now<state.readyAt;const curtain=host.querySelector('.race-curtain');if(curtain)curtain.hidden=!waiting;const counter=host.querySelector('[data-race-countdown]');if(counter)counter.textContent=state.status==='loading'?(state.solo?'正在准备下一关…':'等待双方就绪…'):String(Math.max(1,Math.ceil((state.readyAt-now)/1000)));const time=host.querySelector('[data-race-time]');if(time)time.textContent=fmt(now-(state.solo?state.startAt:state.readyAt));const h=gameHost();if(h)h.inert=waiting||busy;}
async function submit(answer){if(transitionTimer||busy||!state||Date.now()+offset<state.readyAt)return;busy=true;updateClock();try{apply(await api('submit',{round:state.round,state:answer}));}catch(e){notice(e.message);}finally{busy=false;updateClock();}}
function answerCard(item,i,compact=false){const l=item.level,n=l.size,cells=new Map();if(game==='repair'){(l.blocked||[]).forEach(c=>cells.set(c[1]*n+c[0],{blocked:true}));(l.fixed||[]).forEach(c=>cells.set(c[1]*n+c[0],{color:c[2],label:'▣'}));item.answer.forEach((p,j)=>p.cells.forEach(c=>cells.set((p.y+c[1])*n+p.x+c[0],{color:p.color,label:j+1})));}else{(l.sockets||[]).forEach(([x,y])=>cells.set(y*n+x,{color:'socket',label:'·'}));item.answer.forEach(p=>cells.set(p.y*n+p.x,{color:'balloon lift-'+p.lift,label:p.lift}));}return `<article class="race-answer"><h3>第 ${i+1} 题</h3><div class="race-answer-grid" style="--n:${n}">${Array.from({length:n*n},(_,j)=>{const c=cells.get(j);return `<i class="${c?.color||''}">${c?.blocked?'⊘':c?.label||''}</i>`;}).join('')}</div>${compact===true?`<button data-copy-text="${esc(item.seed)}">复制种子</button>`:`<textarea readonly aria-label="第 ${i+1} 题种子">${esc(item.seed)}</textarea><button data-copy="${i}">复制种子</button>`}</article>`;}
function seedPreview(seed,i){try{const level=(game==='repair'?window.CustomRepair:window.CustomSalvage).decode(seed);const answer=game==='repair'?level.pieces.map(p=>({...p,x:0,y:0})):level.answer;return answerCard({level,answer,seed},i,true);}catch{return `<article class="race-answer"><h3>第 ${i+1} 题</h3><div class="race-preview-unavailable">无法解析预览</div><button data-copy-text="${esc(seed)}">复制种子</button></article>`;}}
async function listing(history){await identity();const records=await api(`${history?'history':'leaderboard'}?game=${game}&mode=${mode}`);page='list';shell(`<h1>${history?'个人历史':'排行榜'} · ${mode==='easy'?'简单':'混沌'}</h1><p>每次独立随机 5 题，难度仅按模式分组，不代表题目难度完全相同。</p>${records.length?records.map((r,i)=>`<details><summary>${history?new Date(r.at).toLocaleString():'#'+r.rank}　${esc(r.nickname)}　${fmt(r.elapsed)}${r.mine?' · 你':''}</summary><div class="race-history-previews">${r.seeds.map(seedPreview).join('')}</div></details>`).join(''):'<p>暂无成绩。</p>'}`);}
async function act(action){try{
 if(action==='connect'){const val=host.querySelector('#race-api').value.trim().replace(/\/$/,'');if(val&&!/^https?:\/\//.test(val))throw Error('请输入 http:// 或 https:// 服务地址');base=val;storage.set('race.api',base);token='';me='';await connect();notice('已连接');return;}
 if(action==='back'){if(page==='review'){page='result';viewKey='';apply(state);return;}if(['playing','room','result'].includes(page))return act('leave');if(page==='list'){menu();return;}closed=true;clearPolling();stopGame();host.hidden=true;document.querySelector('.terminal').inert=false;engine().open();return;}
 if(action==='copy-room'){await navigator.clipboard.writeText(state.code);notice('房间码已复制');return;}
 if(action==='leave'){await api('leave',{});state=null;menu();return;}
 if(action==='leaderboard'||action==='history')return await listing(action==='history');
 if(action==='review'){page='review';shell(`<button data-act="back">‹ 返回竞速结算</button><h1>赛后复盘</h1><p>显示其中一种合法解；复制种子后可在自定义关卡中导入。</p><div class="race-review">${state.review.map(answerCard).join('')}</div>`);host.querySelectorAll('[data-copy]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(state.review[+b.dataset.copy].seed);b.textContent='已复制';}catch{notice('请选中种子文本手动复制。');}});return;}
 if(action==='wait'){page='room';shell('<h1>等待房主再来一局</h1><button data-act="leave">离开</button>');startPolling();return;}
 let s;if(['solo','create','join'].includes(action)){await identity();notice('正在生成可解关卡…');s=await api(action,{game,mode,count:Number(host.querySelector('#race-count')?.value||5),code:host.querySelector('#race-code')?.value});}
 else if(action==='again'){s=await api('solo',{game,mode});}
 else if(action==='configure')s=await api('configure',{mode:host.querySelector('#room-mode').value,count:+host.querySelector('#room-count').value});
 else if(['start','skip','kick'].includes(action))s=await api(action,{});
 if(s){apply(s);startPolling();}
 }catch(e){notice(e.message);}}
 host.addEventListener('click',e=>{const copy=e.target.closest('[data-copy-text]');if(copy){navigator.clipboard.writeText(copy.dataset.copyText).then(()=>copy.textContent='已复制').catch(()=>notice('复制失败，请允许浏览器访问剪贴板后重试。'));return;}const b=e.target.closest('[data-act]');if(b&&!b.disabled)act(b.dataset.act);});
 window.RaceChallenge={open};
})();
